        "<td style='width:160px;text-align:right'><button class='btn ghost small' data-key-listen='" + esc(a.id) + "'>" + (b ? "Change" : "Set") + "</button>" + (b && a.id !== "menu" ? " <button class='btn ghost small' data-key-clear='" + esc(a.id) + "'>Clear</button>" : "") + "</td></tr>";
